/**
 * TBI-018 s3d-3a: queue tickets of the Session Host (docs/plans/S3D-HOST-WIRING-DESIGN.md section 4,
 * ops review M2). s3d-3b: owned by SessionHost.admitCreate (issue / poll / started / dropped) and
 * `DELETE /sessions/queue` (forget), only with an enabled sim adapter.
 *
 * A queue ticket is a capability of a waiting client: `randomBytes(16)` base64url (22 characters),
 * generated by the server only, carried in the `Tbi-Queue-Ticket` request header (never the URL, never
 * `X-Tbi-*`, which the reverse proxy strips). It carries no identity: every operation also needs the
 * caller's principal, and a foreign ticket is indistinguishable from an unknown one.
 *
 * Registry rules (M2):
 *   - states: waiting, started { sessionId }, dropped { reason: 'replaced' } or dropped { limit };
 *   - at most one waiting ticket per principal: a new one replaces the old, which becomes dropped with
 *     reason 'replaced' (its tab's next poll answers 409 queue_replaced in s3d-3b);
 *   - TTL per entry (`ttlMs`, host config: queue.maxWaitMs + queue.vanishMs), counted from the entry's
 *     last state change (a state changes at most twice, so an entry lives at most 2 x ttlMs);
 *   - a per-principal cap (oldest of that principal first) and a global cap with oldest-first eviction.
 *     The per-principal cap bounds how many entries one principal holds (so one principal alone can
 *     never fill the registry when perPrincipalCap < cap), but it does NOT protect other principals:
 *     once the registry is at the global cap, ANY issue, also one from a principal below its own cap,
 *     evicts the oldest entry, whoever owns it. An evicted ticket behaves exactly as an unknown one; an
 *     evicted (or expired) WAITING ticket is reported by `issue` in `evicted`, so the host can cancel
 *     its queue entry as well (s3d-3a review note 2);
 *   - memory only, per process (a restart forgets every ticket: the waiter re-joins);
 *   - this module never logs, and nothing it returns besides `issue` contains a ticket value.
 */
import { randomBytes } from 'node:crypto';
import type { IncomingMessage } from 'node:http';
import type { Clock } from '../plans/time.js';
import { SESSION_ID_RE } from './session.js';
import type { PublicLimit } from './simAdmission.js';

/** The client understands 202 + polling (value exactly `1`). Node lower-cases header names. */
export const QUEUE_HEADER = 'tbi-queue';
/** The waiting client's ticket on a poll or a cancel. */
export const QUEUE_TICKET_HEADER = 'tbi-queue-ticket';

const TICKET_BYTES = 16;
/** 16 bytes base64url, unpadded: 22 characters, the last one carries 2 data bits (low 4 bits zero). */
export const QUEUE_TICKET_RE = /^[A-Za-z0-9_-]{21}[AQgw]$/;

/** Strict format check: exactly the canonical encoding of 16 bytes. */
export function isQueueTicket(v: unknown): v is string {
  if (typeof v !== 'string' || v.length !== 22 || !QUEUE_TICKET_RE.test(v)) return false;
  const raw = Buffer.from(v, 'base64url');
  return raw.length === TICKET_BYTES && raw.toString('base64url') === v;
}

/** A fresh server-generated ticket. */
export function newQueueTicket(): string {
  return randomBytes(TICKET_BYTES).toString('base64url');
}

const single = (h: string | string[] | undefined): string | undefined =>
  typeof h === 'string' ? h : undefined; // a repeated header is never one value

/** `Tbi-Queue: 1` exactly; anything else (absent, repeated, other values) is a legacy client. */
export function queueCapable(req: Pick<IncomingMessage, 'headers'>): boolean {
  return single(req.headers[QUEUE_HEADER]) === '1';
}

/** The `Tbi-Queue-Ticket` header if it is a well-formed ticket; malformed or absent = no ticket. */
export function queueTicketOf(req: Pick<IncomingMessage, 'headers'>): string | null {
  const v = single(req.headers[QUEUE_TICKET_HEADER]);
  return isQueueTicket(v) ? v : null;
}

export type TicketState =
  | { kind: 'waiting' }
  | { kind: 'started'; sessionId: string }
  | { kind: 'dropped'; reason: 'replaced' }
  | { kind: 'dropped'; reason: 'limit'; limit: PublicLimit };

interface Entry {
  principal: string;
  state: TicketState;
  expiresAt: number;
}

export interface TicketRegistryOptions {
  /** lifetime of an entry after its last state change: queue.maxWaitMs + queue.vanishMs */
  ttlMs: number;
  /** most entries in total (host config) */
  cap: number;
  /** most entries of one principal (>= 2: its waiting ticket and the one it replaced) */
  perPrincipalCap: number;
  clock: Clock;
}

const posInt = (v: unknown): v is number => Number.isSafeInteger(v) && (v as number) >= 1;

export class TicketRegistry {
  /** insertion order = creation order (entries are never re-inserted): oldest first */
  private readonly entries = new Map<string, Entry>();
  /** principal -> its waiting ticket */
  private readonly waiting = new Map<string, string>();
  /** principal -> its tickets in creation order (index for the per-principal cap; no full scan) */
  private readonly byPrincipal = new Map<string, Set<string>>();
  private readonly ttlMs: number;
  private readonly cap: number;
  private readonly perPrincipalCap: number;
  private readonly clock: Clock;

  constructor(opts: TicketRegistryOptions) {
    if (!posInt(opts.ttlMs)) throw new Error('ticket registry: ttlMs must be a positive integer');
    if (!posInt(opts.cap)) throw new Error('ticket registry: cap must be a positive integer');
    if (
      !posInt(opts.perPrincipalCap) ||
      opts.perPrincipalCap < 2 ||
      opts.perPrincipalCap > opts.cap
    )
      throw new Error('ticket registry: perPrincipalCap must be between 2 and cap');
    this.ttlMs = opts.ttlMs;
    this.cap = opts.cap;
    this.perPrincipalCap = opts.perPrincipalCap;
    this.clock = opts.clock;
  }

  /** Entries currently held (expired ones may still count until the next sweep). */
  get size(): number {
    return this.entries.size;
  }

  private now(): number {
    const t = this.clock.now();
    if (!Number.isFinite(t)) throw new Error('ticket registry: no trustworthy time');
    return t;
  }

  /** Remove an entry; returns it (null when unknown). */
  private remove(ticket: string): Entry | null {
    const e = this.entries.get(ticket);
    if (!e) return null;
    this.entries.delete(ticket);
    if (this.waiting.get(e.principal) === ticket) this.waiting.delete(e.principal);
    const own = this.byPrincipal.get(e.principal);
    own?.delete(ticket);
    if (own?.size === 0) this.byPrincipal.delete(e.principal);
    return e;
  }

  /** Remove `ticket` and report it in `out` when it was waiting (its queue entry must go too). */
  private evict(ticket: string, out: { ticket: string; principal: string }[]): void {
    const e = this.remove(ticket);
    if (e?.state.kind === 'waiting') out.push({ ticket, principal: e.principal });
  }

  private sweepInto(now: number, out: { ticket: string; principal: string }[]): number {
    let n = 0;
    for (const [t, e] of [...this.entries])
      if (now >= e.expiresAt) {
        this.evict(t, out);
        n++;
      }
    return n;
  }

  /** Remove every expired entry. Returns how many were removed (a count, never tickets). */
  sweep(): number {
    return this.sweepInto(this.now(), []);
  }

  /**
   * A new waiting ticket for `principal` (the only way an entry is created). Its previous waiting
   * ticket, if any, becomes dropped 'replaced'. Never exceeds `perPrincipalCap` for the principal nor
   * `cap` in total (oldest first). `ticket`: a server-generated ticket the host already handed to the
   * sim adapter (s3d-3b: the entry is created only after admission said queued or start); it must be
   * well-formed and unknown, otherwise this throws (a host bug). Absent: a fresh one.
   * Returned: the ticket (the only place a ticket value leaves besides `evicted`) and `evicted`, the
   * WAITING tickets this call removed (expired or capped), whose queue entries the caller cancels.
   * Cost: the expiry sweep (a full pass) runs only when the registry is at its cap; otherwise O(1)
   * apart from the principal's own entries (at most perPrincipalCap).
   */
  issue(
    principal: string,
    ticket?: string,
  ): { ticket: string; replaced: boolean; evicted: { ticket: string; principal: string }[] } {
    if (typeof principal !== 'string' || principal === '')
      throw new Error('ticket registry: principal required');
    if (ticket !== undefined && (!isQueueTicket(ticket) || this.entries.has(ticket)))
      throw new Error('ticket registry: malformed or duplicate ticket');
    const now = this.now();
    const evicted: { ticket: string; principal: string }[] = [];
    if (this.entries.size >= this.cap) this.sweepInto(now, evicted);
    const old = this.waiting.get(principal);
    if (old !== undefined) {
      const e = this.entries.get(old) as Entry;
      e.state = { kind: 'dropped', reason: 'replaced' };
      e.expiresAt = now + this.ttlMs;
      this.waiting.delete(principal);
    }
    const own = this.byPrincipal.get(principal);
    while (own !== undefined && own.size >= this.perPrincipalCap)
      this.evict(own.values().next().value as string, evicted);
    while (this.entries.size >= this.cap)
      this.evict(this.entries.keys().next().value as string, evicted);
    let t = ticket ?? newQueueTicket();
    while (this.entries.has(t)) t = newQueueTicket();
    this.entries.set(t, {
      principal,
      state: { kind: 'waiting' },
      expiresAt: now + this.ttlMs,
    });
    this.waiting.set(principal, t);
    const mine = this.byPrincipal.get(principal) ?? new Set<string>();
    mine.add(t);
    this.byPrincipal.set(principal, mine);
    return { ticket: t, replaced: old !== undefined, evicted };
  }

  /**
   * s3d-3b: `principal`'s waiting ticket (if any) -> dropped { limit } (the adapter refused or lost the
   * principal's entry outside a poll of that ticket). Returns whether one changed; never a ticket.
   */
  dropWaitingOf(principal: string, limit: PublicLimit): boolean {
    const t = this.waiting.get(principal);
    return t === undefined ? false : this.markDropped(t, principal, limit);
  }

  /** The live entry of `ticket` if it belongs to `principal`; unknown, expired, foreign: null. */
  private own(ticket: unknown, principal: string): Entry | null {
    if (!isQueueTicket(ticket)) return null;
    const e = this.entries.get(ticket);
    if (!e) return null;
    if (this.now() >= e.expiresAt) {
      this.remove(ticket);
      return null;
    }
    return e.principal === principal ? e : null;
  }

  /** The state of `principal`'s ticket (a copy). Unknown, expired, evicted and foreign are all null. */
  lookup(ticket: unknown, principal: string): TicketState | null {
    const e = this.own(ticket, principal);
    return e ? (structuredClone(e.state) as TicketState) : null;
  }

  /** waiting -> started. False (nothing changed) for any other state, or an unknown/foreign ticket. */
  markStarted(ticket: unknown, principal: string, sessionId: string): boolean {
    if (typeof sessionId !== 'string' || !SESSION_ID_RE.test(sessionId)) return false;
    const e = this.own(ticket, principal);
    if (!e || e.state.kind !== 'waiting') return false;
    e.state = { kind: 'started', sessionId };
    e.expiresAt = this.now() + this.ttlMs;
    this.waiting.delete(principal);
    return true;
  }

  /** waiting -> dropped { limit } (the adapter dropped the waiter). False otherwise. */
  markDropped(ticket: unknown, principal: string, limit: PublicLimit): boolean {
    const e = this.own(ticket, principal);
    if (!e || e.state.kind !== 'waiting') return false;
    e.state = { kind: 'dropped', reason: 'limit', limit: structuredClone(limit) };
    e.expiresAt = this.now() + this.ttlMs;
    this.waiting.delete(principal);
    return true;
  }

  /** Remove `principal`'s ticket (cancel). Unknown or foreign: false, nothing changed. */
  forget(ticket: unknown, principal: string): boolean {
    const e = this.own(ticket, principal);
    if (!e) return false;
    this.remove(ticket as string);
    return true;
  }

  /** Counts per state (for coarse health numbers later; never principals or tickets). */
  counts(): { waiting: number; started: number; dropped: number } {
    const out = { waiting: 0, started: 0, dropped: 0 };
    for (const e of this.entries.values()) out[e.state.kind]++;
    return out;
  }
}
